/**
 * Checklist tab (owner 2026-11-23): the mass-production checklist, GENERATED by the server from this production's assembly steps,
 * process sections, parts, open discussion and missing certification evidence.  Nothing is typed here except the status of an item and
 * its evidence; an item whose requirement text changed returns to "To confirm".  The owner / engineer and the factory set statuses.
 * The Excel file (EN + 中文) is an export only.
 */
import React, { useCallback, useEffect, useState } from 'react';
import { Box, Button, Checkbox, Chip, FormControlLabel, MenuItem, Paper, TextField, Typography } from '@mui/material';
import { useTranslation } from 'react-i18next';
import HelpTip from '../../../components/common/HelpTip';
import { useRememberedView } from '../../../lib/useRememberedView';
import { checklistApi, CHECKLIST_STATUSES, groupItems, pick, type ChecklistData, type ChecklistItem, type ChecklistStatus } from '../checklistApi';
import { productionApi } from '../api';
import type { DocumentRec, ProdCtx } from '../types';

const STATUS_COLOR: Record<ChecklistStatus, string> = { to_do: '#9ca3af', to_confirm: '#d97706', missing_info: '#dc2626', optional: '#2563eb', done: '#16a34a' };
const asBool = (raw: unknown): boolean | null => (typeof raw === 'boolean' ? raw : null);

const ChecklistPanel: React.FC<{ ctx: ProdCtx; documents: DocumentRec[] }> = ({ ctx, documents }) => {
  const { t } = useTranslation('production');
  const [data, setData] = useState<ChecklistData | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [openOnly, setOpenOnly] = useRememberedView<boolean>(`production.checklist.openOnly.${ctx.die}|${ctx.config}`, false, asBool);
  const fail = (e: unknown) => setErr(t('failed', { reason: e instanceof Error ? e.message : String(e) }));
  const load = useCallback(() => { void checklistApi.get(ctx.die, ctx.config).then((d) => { setData(d); setErr(null); }).catch(fail); },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [ctx.die, ctx.config]);
  useEffect(load, [load]);

  const save = async (it: ChecklistItem, status: ChecklistStatus, evidence?: { doc_id: string | null; note: string }) => {
    setBusy(it.key);
    try {
      const next = await checklistApi.setStatus(ctx.die, ctx.config, it.key, status, evidence);
      setData((d) => (d ? { ...d, items: d.items.map((x) => (x.key === next.key ? next : x)) } : d));
      load();
    } catch (e) { fail(e); } finally { setBusy(null); }
  };
  const upload = async (it: ChecklistItem, files: FileList | null) => {
    if (!files?.length) return;
    setBusy(it.key);
    try {
      const doc = await productionApi.uploadDocument(ctx.die, ctx.config, files[0], null);
      await checklistApi.setStatus(ctx.die, ctx.config, it.key, it.status, { doc_id: doc.id, note: it.evidence?.note ?? '' });
      ctx.reload(); load();
    } catch (e) { fail(e); } finally { setBusy(null); }
  };

  const groups = data ? groupItems(data.items, openOnly) : [];
  const editable = !!data?.can_edit;
  return (
    <Box data-testid="checklist-panel">
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1, flexWrap: 'wrap' }}>
        <Typography sx={{ fontSize: 12, color: 'var(--text-3)' }}>{t('tabs.checklist')}</Typography>
        <HelpTip title={t('checklist.tip')} />
        {data && <Chip size="small" label={t('checklist.revision', { rev: data.revision.number })} sx={{ height: 18, fontSize: 10.5 }} />}
        {data && <Chip size="small" label={t('checklist.openCount', { open: data.stats.open, total: data.stats.total })} sx={{ height: 18, fontSize: 10.5 }} />}
        {data && <Chip size="small" label={`${data.stats.done_pct} %`} sx={{ height: 18, fontSize: 10.5, bgcolor: STATUS_COLOR.done, color: '#fff' }} />}
        <FormControlLabel sx={{ m: 0, ml: 'auto' }} control={<Checkbox size="small" checked={openOnly} onChange={(e) => setOpenOnly(e.target.checked)} />}
          label={<Typography sx={{ fontSize: 12.5 }}>{t('checklist.openOnly')}</Typography>} />
        <Button size="small" variant="outlined" sx={{ textTransform: 'none' }} onClick={() => void checklistApi.downloadXlsx(ctx.die, ctx.config).catch(fail)}>{t('checklist.download')}</Button>
        <HelpTip title={t('checklist.downloadTip')} />
      </Box>
      {err && <Typography role="alert" sx={{ fontSize: 11, color: '#f87171', mb: 1 }}>{err}</Typography>}
      {data && groups.length === 0 && <Typography sx={{ fontSize: 13, color: 'var(--text-4)' }}>{t('checklist.none')}</Typography>}
      {groups.map((g) => (
        <Box key={g.category} sx={{ mb: 2 }} data-testid="checklist-group">
          <Typography sx={{ fontSize: 12.5, fontWeight: 800, mb: 0.75 }}>{t(`checklist.categories.${g.category}`)}</Typography>
          <Paper sx={{ bgcolor: 'var(--panel-2)', border: '1px solid var(--line-soft)', borderRadius: 1.5 }}>
            {g.items.map((it, i) => (
              <Box key={it.key} data-testid="checklist-item" data-item-id={it.key}
                sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', alignItems: 'flex-start', p: 1, borderTop: i ? '1px solid var(--panel)' : 'none' }}>
                <Typography sx={{ width: 28, fontSize: 11.5, color: 'var(--text-3)', flexShrink: 0 }}>{it.no}</Typography>
                <Box sx={{ flex: '1 1 320px', minWidth: 0 }}>
                  <Typography sx={{ fontSize: 12.5, fontWeight: 700, overflowWrap: 'anywhere' }}>{pick(it.item, ctx.uiLang)}</Typography>
                  {pick(it.requirement, ctx.uiLang) && (
                    <Typography sx={{ fontSize: 12, color: 'var(--text-2)', whiteSpace: 'pre-line', overflowWrap: 'anywhere', maxHeight: 120, overflowY: 'auto' }}>{pick(it.requirement, ctx.uiLang)}</Typography>
                  )}
                </Box>
                <Chip size="small" label={t(`checklist.responsible.${it.responsible}`)} title={pick(it.how, ctx.uiLang)} sx={{ height: 18, fontSize: 10.5 }} />
                {editable ? (
                  <TextField select size="small" label={t('checklist.status')} value={it.status} disabled={busy === it.key} sx={{ minWidth: 150 }}
                    onChange={(e) => void save(it, e.target.value as ChecklistStatus)}>
                    {CHECKLIST_STATUSES.map((s) => <MenuItem key={s} value={s}>{t(`checklist.statuses.${s}`)}</MenuItem>)}
                  </TextField>
                ) : (
                  <Chip size="small" label={t(`checklist.statuses.${it.status}`)} sx={{ height: 20, fontSize: 10.5, bgcolor: STATUS_COLOR[it.status], color: '#fff' }} />
                )}
                {it.changed && <Chip size="small" color="warning" label={t('checklist.changed')} title={t('checklist.changedTip')} sx={{ height: 18, fontSize: 10.5 }} />}
                {editable ? (
                  <TextField select size="small" label={t('checklist.evidence')} value={it.evidence?.doc_id ?? ''} disabled={busy === it.key} sx={{ minWidth: 180, maxWidth: 240 }}
                    onChange={(e) => void save(it, it.status, { doc_id: e.target.value || null, note: it.evidence?.note ?? '' })}>
                    <MenuItem value="">{t('checklist.noEvidence')}</MenuItem>
                    {documents.map((d) => <MenuItem key={d.id} value={d.id}>{d.name}</MenuItem>)}
                  </TextField>
                ) : (it.evidence?.name && <Typography sx={{ fontSize: 11.5 }}>{it.evidence.name}</Typography>)}
                {editable && (
                  <Button size="small" component="label" disabled={busy === it.key} sx={{ textTransform: 'none', fontSize: 11 }} title={t('checklist.uploadTip')}>
                    {t('docs.upload')}<input type="file" hidden onChange={(e) => { void upload(it, e.target.files); e.target.value = ''; }} />
                  </Button>
                )}
                {it.by && <Typography sx={{ fontSize: 10.5, color: 'var(--text-4)' }} title={t('checklist.byTip', { by: it.by, at: it.at ?? '' })}>{it.by.split('@')[0]}</Typography>}
              </Box>
            ))}
          </Paper>
        </Box>
      ))}
    </Box>
  );
};

export default ChecklistPanel;
